import{_ as o,B as i,c as n,a3 as a,G as s,w as d,o as l,j as e}from"./chunks/framework.BSKDiXd-.js";const x=JSON.parse('{"title":"Starter Guide","description":"","frontmatter":{"outline":"deep","next":{"text":"Load","link":"/guide/starter/load"}},"headers":[],"relativePath":"guide/starter/index.md","filePath":"guide/starter/index.md"}'),c={name:"guide/starter/index.md"};function h(p,t,m,g,u,f){const r=i("ClientOnly");return l(),n("div",null,[t[1]||(t[1]=a('<h1 id="starter-guide" tabindex="-1">Starter Guide <a class="header-anchor" href="#starter-guide" aria-label="Permalink to &quot;Starter Guide&quot;">​</a></h1><p>Graphane is a free and open-source <strong>data visualization low-level microframework</strong> designed to facilitate the creation of custom, dynamic and interactive visualizations. Graphane offers <strong>flexibility in designs</strong>, allowing creators to make unique aesthetic visualizations that are far from becoming monotonous charts seen everywhere.</p><p>Graphane is composed of:</p><ul><li><a href="./composer.html"><strong>A web component</strong></a> for combining: <ul><li><a href="./template.html"><strong>SVG template</strong></a> with directives.</li><li><a href="./data.html"><strong>Data</strong></a> in JSON or CSV formats.</li><li><a href="./methods.html"><strong>Methods</strong></a>, optionally, to handle interactivity and data transformation.</li></ul></li></ul><p>This is a basic example:</p>',5)),s(r,null,{default:d(()=>t[0]||(t[0]=[e("g-composer",{id:"example-starter"},[e("svg",{viewBox:"0 0 200 100",width:"200px",height:"100px"},[e("g",{"stroke-width":"12","stroke-linecap":"round"},[e("defs",{"g-for":"(record, index) of data"},[e("line",{x1:"22","g-bind:x2":"record.value","g-bind:y1":"index * 20 + 30","g-bind:y2":"index * 20 + 30","g-bind:stroke":"record.color"})])])]),e("g-script",{type:"data"},' [ { color: "#D80000", value: 130 }, { color: "#00D800", value: 170 }, { color: "#0000D8", value: 100 }, ] ')],-1),e("g-editor",{href:"#example-starter"},null,-1)])),_:1}),t[2]||(t[2]=a('<p>Graphane is based on SVG and directives, defining a <strong>declarative way</strong> to build <strong>data-driven</strong> graphics. This approach allows centering the effort on the design in a very natural form. Designers and developers achieve technical efficiency and gain the means to communicate their data story to their audience effectively.</p><p>In addition, Graphane has a <strong>smooth rendering</strong> and <strong>optimal performance</strong> with a **tiny overhead **. It is not just a tool but a complete system that includes specially designed mechanisms to update the visualization efficiently when data are changed. This feature allows Graphane to maintain high runtime performance without the need for pre-compilation processes.</p><blockquote><p>For more details, see <a href="./../in-depth/architecture/why.html">Why Graphane?</a>.</p></blockquote>',3))])}const y=o(c,[["render",h]]);export{x as __pageData,y as default};
